import { Component, Input, Output } from '@angular/core';

interface Course {
  id: string;
  title: string;
  description: string;
  creationDate: string | Date;
  duration: number;
  authors: string[];
}

@Component({
  selector: 'app-course-info',
  templateUrl: './course-info.component.html',
  styleUrls: ['./course-info.component.scss']
})
export class CourseInfoComponent {
   @Input() course!: Course;

   @Output() back = () => {
}
<div class="title">{{ course.title }}</div>
<div class="course-info">
  <div class="course-info__description">
    {{ course.description }}
  </div>
  <div class="course-info__info">
    <div><b>ID: </b><span class="course-info__info-id">{{ course.id }}</span></div>
    <div><b>Duration: </b><span class="course-info__info-duration">{{ course.duration | duration}}</span></div>
    <div><b>Created: </b><span class="course-info__info-date">{{ course.creationDate | customDate }}</span></div>
    <div><b>Authors: </b><span class="course-info__info-authors">{{ course.authors.join(', ') }}</span></div>
  </div>
</div>
<div class="navigation-block">
  <app-button buttonText="Back" click="onBack()"></app-button> - має повертати на список курсів course.component
